// linkParents points ci's columns for its nested ancestors at their rows,
// found in known (rows a Batch is creating, by name) or else looked up by
// name: a nested resource's row is keyed by a surrogate of its own, not by
// its id.
func (r *GraphQLBookingRuleRepository) linkParents(ctx context.Context, ci *resourceql.CreateInput, name string, known map[string]string) error {
	ids, err := repox.SplitName(name, "hotels", "ratePlans", "bookingRules")
	if err != nil {
		return err
	}
	{
		n := "hotels/" + ids[0] + "/ratePlans/" + ids[1]
		if k, ok := known[n]; ok {
			ci.RatePlanId = k
		} else if k, found, err := rateplanResourceKey(ctx, r.Svc, n); err != nil {
			return err
		} else if found {
			ci.RatePlanId = k
		}
	}
	return nil
}

