// List returns one page of records under parent.
func (r *GraphQLBookingRuleRepository) List(ctx context.Context, parent string, in repox.ListInput) ([]*booking_rulev1.BookingRule, string, error) {
	parentIDs, err := repox.SplitName(parent, "hotels", "ratePlans")
	if err != nil {
		return nil, "", err
	}
	// AIP-159: "-" for the parent reads across every parent.
	if parentIDs[len(parentIDs)-1] == "-" {
		return r.list(ctx, in)
	}
	// The parent is nested, so its row is found by name.
	keys, err := rateplanResourceKeys(ctx, r.Svc, parent)
	if err != nil {
		return nil, "", err
	}
	return r.list(ctx, in, resourceql.RatePlanId.In(keys...))
}

func (r *GraphQLBookingRuleRepository) list(ctx context.Context, in repox.ListInput, scope ...graphql.Predicate) ([]*booking_rulev1.BookingRule, string, error) {
	if !in.ShowDeleted {
		scope = append(scope, resourceql.DeleteTime.IsNull(true))
	}
	conds, err := filterx.Parse(in.Filter)
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	conds = append(conds, in.Where...)
	if err := repox.CheckReadMask((*booking_rulev1.BookingRule)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	eng := filterx.Hasura[resourceql.BookingruleResource](bookingrule.BookingRuleFilterSpec, r.Svc.Query.Bookingrule.Resource).Scope(scope...)
	for f, h := range r.ListOverrides {
		eng.Override(f, h)
	}
	rows, next, err := eng.List(ctx, filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*booking_rulev1.BookingRule, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i], in.ReadMask)
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

