// newInput builds the insert a Batch queues for in under parent, and
// the record it stands for, named: the same resolution Create applies.
func (r *GraphQLBookingRuleRepository) newInput(parent string, in *booking_rulev1.BookingRule) (resourceql.CreateInput, *booking_rulev1.BookingRule, error) {
	var ci resourceql.CreateInput
	parentIDs, err := repox.SplitName(parent, "hotels", "ratePlans")
	if err != nil {
		return ci, nil, err
	}
	id := repox.NewULID()
	rowID := id
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "hotels", "ratePlans", "bookingRules")
		if err != nil {
			return ci, nil, err
		}
		for i := range parentIDs {
			if ids[i] != parentIDs[i] {
				return ci, nil, fmt.Errorf("%w: name %q is not under parent %q", repox.ErrInvalidArgument, in.GetName(), parent)
			}
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*booking_rulev1.BookingRule)
	in.Name = FormatBookingRuleName(parentIDs[0], parentIDs[1], id)
	id = rowID // keyed as Create keys it
	ci = bookingRuleToCreateInput(in)
	ci.Id = id
	ci.HotelId = parentIDs[0]
	ci.RatePlanId = parentIDs[1]
	ci.Etag = repox.NewULID()
	now := tsToStr(timestamppb.New(time.Now().UTC()))
	ci.CreateTime = now
	ci.UpdateTime = now
	return ci, in, nil
}

