// UpdateBookingRuleOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards
// it, and a guarded update runs ahead of the batch (see graphQLBatch).
func (b *graphQLBatch) UpdateBookingRuleOutputOnly(in *booking_rulev1.BookingRule, paths []string) {
	if len(paths) == 0 {
		b.u.Fail(fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument))
		return
	}
	if _, err := repox.SplitName(in.GetName(), "hotels", "ratePlans", "bookingRules"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLBookingRuleRepository{Svc: b.svc}
	patch := bookingRuleToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/BookingRule", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getBookingRule)})
	if etag := in.GetEtag(); etag != "" {
		b.u.QueueGraphQLAhead(func(ctx context.Context) error {
			id, err := b.rowID(ctx, in.GetName(), r.rowID)
			if err != nil {
				return err
			}
			_, err = b.svc.Mutation.Bookingrule.Resource.UpdateIfMatch(ctx, id, patch, resourceql.Etag.Eq(etag))
			return mapGraphQLErr(err)
		})
		return
	}
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Bookingrule.Resource.UpdateOp(id, patch, new(resourceql.UpdateBookingruleResourceByIdResponse)))
		return nil, nil
	})
}

